from __future__ import annotations

from pathlib import Path

import polars as pl
import pytest
from ds.data.chars import CharId
from ds.data.raw.ultimateframedata.stats import SITE_CHARACTER, SiteChangedError, StatsPage, parse_stats

PAGE = Path(__file__).parent / "pages" / "ultimateframedata_stats.html"


@pytest.fixture(scope="module")
def page() -> StatsPage:
    return parse_stats(PAGE.read_text())


def _main(page: StatsPage, char_id: str) -> dict:
    rows = page.char_stats.filter((pl.col("char_id") == char_id) & pl.col("variant").is_null())
    assert rows.height == 1
    return rows.row(0, named=True)


def test_every_fighter_has_one_main_row(page: StatsPage) -> None:
    main = page.char_stats.filter(pl.col("variant").is_null())
    assert sorted(main["char_id"]) == sorted(c.value for c in CharId)
    assert page.char_stats.select("char_id", "variant").is_duplicated().sum() == 0
    assert page.unmatched == []


def test_values_are_typed(page: StatsPage) -> None:
    schema = page.char_stats.schema
    assert schema["weight"] == pl.Int16
    assert schema["fall_speed"] == pl.Float64
    assert schema["oos_1_moves"] == pl.String
    assert _main(page, "bowser")["weight"] == 135
    mac = _main(page, "little_mac")
    assert (mac["fall_speed"], mac["fast_fall_speed"]) == (1.95, 3.12)


def test_ledge_and_out_of_shield(page: StatsPage) -> None:
    mario = _main(page, "mario")
    ledge_attack = ("ledge_attack_intangible", "ledge_attack_total", "ledge_attack_on_shield")
    assert tuple(mario[c] for c in ledge_attack) == (26, 55, -22)
    assert (mario["ledge_getup_intangible"], mario["ledge_getup_total"]) == (33, 34)
    assert mario["ledge_attack_range"] == "F-"
    bayo = _main(page, "bayonetta")
    assert (bayo["oos_1_frame"], bayo["oos_1_moves"]) == (6, "UpB")
    assert _main(page, "ken")["oos_1_frame"] == 5  # '5 (flame), 6 (normal)'


def test_shared_rows_go_to_each_fighter(page: StatsPage) -> None:
    # Landing lists 'Marth/Lucina' once; 'P.T. [Squirtle]' is a site-only name
    assert _main(page, "lucina")["hard_landing_frames"] == _main(page, "marth")["hard_landing_frames"] == 4
    assert _main(page, "pt_squirtle")["oos_1_frame"] is not None
    assert _main(page, "rosalina_and_luma")["weight"] == 82  # site writes 'Rosalina'


def test_variants(page: StatsPage) -> None:
    variants = page.char_stats.filter(pl.col("variant").is_not_null())
    by_key = {(r["char_id"], r["variant"]): r for r in variants.iter_rows(named=True)}
    assert by_key["olimar", "white +2"]["grab_range"] == 35.8
    assert by_key["olimar", "white +2"]["weight"] is None  # a variant row holds only what differs
    assert _main(page, "olimar")["grab_range"] == 24.15  # r/b/y
    assert by_key["ice_climbers", "nana"]["walk_speed"] == 1.1088
    assert _main(page, "ice_climbers")["walk_speed"] == 1.008  # Popo
    assert by_key["rosalina_and_luma", "no luma"]["oos_2_frame"] == 11
    assert _main(page, "steve")["ledge_attack_total"] == 55  # 'Steve (Wood)' is the main row


def test_reflector(page: StatsPage) -> None:
    refl = page.reflector
    orbitars = refl.filter(pl.col("move") == "Guardian Orbitars")
    assert sorted(orbitars["char_id"]) == ["dark_pit", "pit"]  # site row 'Pit & Dark Pit'
    cape = refl.filter((pl.col("char_id") == "mario") & (pl.col("move") == "Cape")).row(0, named=True)
    assert (cape["damage_mult"], cape["speed_mult"], cape["break_threshold_pct"]) == (1.5, 1.0, 50.0)
    assert refl.filter(pl.col("char_id") == "rosalina_and_luma")["damage_mult"].to_list() == [None]  # 'N/A'


def test_site_character_names_real_fighters() -> None:
    ids = {c.value for c in CharId}
    assert all(set(char_ids) <= ids for char_ids, _ in SITE_CHARACTER.values())


def test_missing_section_fails() -> None:
    html = PAGE.read_text().replace("<h2>Weight</h2>", "<h2>Heaviness</h2>")
    with pytest.raises(SiteChangedError, match="Weight"):
        parse_stats(html)
